            if (kbStatus.DirOption.IsSet && kbStatus.Dir == null)
                throw new ArgumentNullException(nameof(kbStatus.Dir), "Property is required for class KbStatus.");

            writer.WriteString("id", kbStatus.Id);

            writer.WriteString("name", kbStatus.Name);

            writer.WriteNumber("docs", kbStatus.Docs);

            writer.WriteNumber("chunks", kbStatus.Chunks);

            writer.WriteNumber("notes", kbStatus.Notes);

            writer.WriteNumber("vectors", kbStatus.Vectors);

            writer.WriteNumber("entities", kbStatus.Entities);

            writer.WriteNumber("edges", kbStatus.Edges);

            writer.WritePropertyName("documents");
            JsonSerializer.Serialize(writer, kbStatus.Documents, jsonSerializerOptions);
            if (kbStatus.VOption.IsSet)
                writer.WriteNumber("v", kbStatus.VOption.Value!.Value);

            if (kbStatus.CreatedAtOption.IsSet)
                writer.WriteNumber("createdAt", kbStatus.CreatedAtOption.Value!.Value);

            if (kbStatus.UpdatedAtOption.IsSet)
                writer.WriteNumber("updatedAt", kbStatus.UpdatedAtOption.Value!.Value);

            if (kbStatus.ProposedOption.IsSet)
                writer.WriteNumber("proposed", kbStatus.ProposedOption.Value!.Value);

            if (kbStatus.ModelOption.IsSet)
                writer.WriteString("model", kbStatus.Model);

            if (kbStatus.DimsOption.IsSet)
                writer.WriteNumber("dims", kbStatus.DimsOption.Value!.Value);

            var embedRawValue = KbStatus.EmbedEnumToJsonValue(kbStatus.EmbedOption.Value!.Value);
            writer.WriteString("embed", embedRawValue);
            if (kbStatus.ReachOption.IsSet)
                writer.WriteString("reach", kbStatus.Reach);

            if (kbStatus.AccessOption.IsSet)
            {
                writer.WritePropertyName("access");
                JsonSerializer.Serialize(writer, kbStatus.Access, jsonSerializerOptions);
            }
            if (kbStatus.BytesOption.IsSet)
                writer.WriteNumber("bytes", kbStatus.BytesOption.Value!.Value);

            if (kbStatus.DirOption.IsSet)
                writer.WriteString("dir", kbStatus.Dir);
        }
    }
